package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import org.mockito.exceptions.base.MockitoException;
import org.mockito.internal.util.Checks;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

public class GenericMetadataSupport_actualTypeArguments_TriageGen0Test {

    private GenericMetadataSupport genericMetadataSupport;
    private Class<?> mockRawType;

    @Before
    public void setUp() {
        // Since GenericMetadataSupport is abstract (due to rawType() being abstract), 
        // we use a spy on a subclass or a mock of the abstract class.
        genericMetadataSupport = spy(new GenericMetadataSupport() {
            @Override
            public Class<?> rawType() {
                return mockRawType;
            }

            @Override
            public List<Type> extraInterfaces() {
                return null;
            }

            @Override
            public Class<?>[] rawExtraInterfaces() {
                return null;
            }

            @Override
            public boolean hasRawExtraInterfaces() {
                return false;
            }

            @Override
            public GenericMetadataSupport resolveGenericReturnType(java.lang.reflect.Method method) {
                return null;
            }
        });
        mockRawType = Object.class;
    }

    @Test
    public void testActualTypeArguments_EmptyParameters() {
        // Arrange
        TypeVariable[] emptyParams = new TypeVariable[0];
        doReturn(emptyParams).when(genericMetadataSupport).rawType().getTypeParameters(); 
        // Note: In real testing of reflection, we must mock the behavior of the underlying calls.
        // Since we cannot easily mock TypeVariable[] returned by rawType().getTypeParameters() 
        // if rawType() returns a real class, we mock the method calls on the spy.

        // Re-mocking approach for abstract method interaction:
        when(genericMetadataSupport.rawType()).thenReturn(Object.class);
        // We need to simulate the behavior of rawType().getTypeParameters()
        // Because rawType() is called inside actualTypeArguments(), we mock it.

        // However, the method calls rawType().getTypeParameters(). 
        // Since rawType() returns Class<?>, we can't mock getTypeParameters() on a real class easily.
        // We will use a Mockito spy setup to handle the internal calls.
    }

    @Test
    public void testActualTypeArguments_WithMultipleParameters() throws Exception {
        // Arrange
        TypeVariable<Object> typeVar1 = mock(TypeVariable.class);
        TypeVariable<Object> typeVar2 = mock(TypeVariable.class);
        TypeVariable[] typeParameters = new TypeVariable[]{typeVar1, typeVar2};

        Type actualType1 = String.class;
        Type actualType2 = Integer.class;

        // Mocking the structure
        // We need to bypass the fact that rawType().getTypeParameters() is a chain.
        // We will mock the internal behavior by overriding the calls via spy.

        // Since we cannot mock the return of rawType().getTypeParameters() directly if rawType() returns a real Class,
        // we simulate the environment.

        // Let's use a more robust way to mock the chain:
        Class<?> mockClass = mock(Class.class);
        when(genericMetadataSupport.rawType()).thenReturn(mockClass);
        when(mockClass.getTypeParameters()).thenReturn(typeParameters);

        doReturn(actualType1).when(genericMetadataSupport).getActualTypeArgumentFor(typeVar1);
        doReturn(actualType2).when(genericMetadataSupport).getActualTypeArgumentFor(typeVar2);

        // Act
        Map<TypeVariable, Type> result = genericMetadataSupport.actualTypeArguments();

        // Assert
        assertNotNull(result);
        assertEquals(2, result.size());
        assertTrue(result.containsKey(typeVar1));
        assertTrue(result.containsKey(typeVar2));
        assertEquals(actualType1, result.get(typeVar1));
        assertEquals(actualType2, result.get(typeVar2));
    }

    @Test
    public void testActualTypeArguments_SingleParameter() throws Exception {
        // Arrange
        TypeVariable<Object> typeVar = mock(TypeVariable.class);
        TypeVariable[] typeParameters = new TypeVariable[]{typeVar};
        Type actualType = Double.class;

        Class<?> mockClass = mock(Class.class);
        when(genericMetadataSupport.rawType()).thenReturn(mockClass);
        when(mockClass.getTypeParameters()).thenReturn(typeParameters);
        doReturn(actualType).when(genericMetadataSupport).getActualTypeArgumentFor(typeVar);

        // Act
        Map<TypeVariable, Type> result = genericMetadataSupport.actualTypeArguments();

        // Assert
        assertEquals(1, result.size());
        assertEquals(actualType, result.get(typeVar));
    }

    @Test
    public void testActualTypeArguments_NullTypeArgument() throws Exception {
        // Arrange
        TypeVariable<Object> typeVar = mock(TypeVariable.class);
        TypeVariable[] typeParameters = new TypeVariable[]{typeVar};

        Class<?> mockClass = mock(Class.class);
        when(genericMetadataSupport.rawType()).thenReturn(mockClass);
        when(mockClass.getTypeParameters()).thenReturn(typeParameters);
        doReturn(null).when(genericMetadataSupport).getActualTypeArgumentFor(typeVar);

        // Act
        Map<TypeVariable, Type> result = genericMetadataSupport.actualTypeArguments();

        // Assert
        assertEquals(1, result.size());
        assertEquals(null, result.get(typeVar));
    }

    // Helper for Mockito mock creation in static context
    @SuppressWarnings("unchecked")
    private static <T> T mock(Class<T> classToMock) {
        return Mockito.mock(classToMock);
    }
}
